import org.elasticsearch.client.RestHighLevelClient;
import org.elasticsearch.client.RequestOptions;
import org.elasticsearch.client.RestClient;
import org.elasticsearch.action.search.SearchRequest;
import org.elasticsearch.action.search.SearchResponse;
import org.elasticsearch.client.indices.GetIndexRequest;
import org.elasticsearch.index.query.BoolQueryBuilder;
import org.elasticsearch.index.query.QueryBuilders;
import org.elasticsearch.search.builder.SearchSourceBuilder;
import org.apache.http.HttpHost;
import org.elasticsearch.client.RestClientBuilder;

import java.io.IOException;
import java.util.List;
import java.util.Arrays;
import java.util.stream.Collectors;

public class ElasticsearchDataFetcher {
    private final RestHighLevelClient client;

    public ElasticsearchDataFetcher(String uri, String username, String password) {
        RestClientBuilder builder = RestClient.builder(
            HttpHost.create(uri)
        )
        .setRequestConfigCallback(requestConfigBuilder -> 
            requestConfigBuilder
                .setConnectTimeout(5000)  // 5 seconds connection timeout
                .setSocketTimeout(10000)  // 10 seconds socket timeout
        )
        .setHttpClientConfigCallback(httpClientBuilder -> 
            httpClientBuilder
                .setDefaultHeaders(Arrays.asList(
                    // Basic auth header
                    new BasicHeader("Authorization", 
                        "Basic " + Base64.getEncoder().encodeToString(
                            (username + ":" + password).getBytes()
                        )
                    )
                ))
        );

        this.client = new RestHighLevelClient(builder);
    }

    /**
     * Fetch data from Elasticsearch based on exact entity word or keyword list match
     * 
     * @param indexName Name of the Elasticsearch index
     * @param entityWord Exact word to match
     * @param keywordsList List of keywords for partial matching
     * @return SearchResponse containing matching documents
     * @throws IOException If there's an error connecting to Elasticsearch
     */
    public SearchResponse fetchData(
        String indexName, 
        String entityWord, 
        List<String> keywordsList
    ) throws IOException {
        // Validate inputs
        if (indexName == null || indexName.isEmpty()) {
            throw new IllegalArgumentException("Index name cannot be null or empty");
        }

        // Create a bool query to handle both exact and partial matching
        BoolQueryBuilder boolQueryBuilder = QueryBuilders.boolQuery();

        // Add exact match for entityWord if provided
        if (entityWord != null && !entityWord.isEmpty()) {
            // Use term query for exact match across all fields
            boolQueryBuilder.should(
                QueryBuilders.termQuery("_all", entityWord)
            );
        }

        // Add partial match for keywords if provided
        if (keywordsList != null && !keywordsList.isEmpty()) {
            // Use match queries for keywords
            keywordsList.forEach(keyword -> 
                boolQueryBuilder.should(
                    QueryBuilders.matchQuery("_all", keyword)
                )
            );
        }

        // Build the search request
        SearchSourceBuilder sourceBuilder = new SearchSourceBuilder()
            .query(boolQueryBuilder)
            .size(100);  // Limit to 100 results, adjust as needed

        SearchRequest searchRequest = new SearchRequest(indexName)
            .source(sourceBuilder);

        // Execute the search and return results
        return client.search(searchRequest, RequestOptions.DEFAULT);
    }

    /**
     * Close the Elasticsearch client connection
     */
    public void close() throws IOException {
        if (client != null) {
            client.close();
        }
    }

    // Example usage method
    public static void main(String[] args) {
        try {
            ElasticsearchDataFetcher fetcher = new ElasticsearchDataFetcher(
                "es-cn-xxx.com:9200", 
                "elastic", 
                "xxxxx"
            );

            // Example of fetching data
            List<String> keywords = Arrays.asList("example", "search");
            SearchResponse response = fetcher.fetchData(
                "your_index_name", 
                "exactEntityWord", 
                keywords
            );

            // Process response...
            fetcher.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
</antArtifact>

